\item[S2] Kaisa Matom\"aki, Maksym Radziwi\l\l, Xuancheng Shao, Terence Tao and Joni Ter\"av\"ainen, \emph{Singmaster's conjecture in the interior of Pascal's triangle}, Quarterly Journal of Mathematics 73 (2022), 1137--1177; arXiv:2106.03335, Section 1, Conjecture 1.1 and (1.1). \url{https://arxiv.org/abs/2106.03335}.
